-- SCWTS 2026-09-15 REQ-03-D01 - idempotent ingest (safe to re-run)

CREATE SCHEMA IF NOT EXISTS daily_task;

CREATE TABLE IF NOT EXISTS daily_task.tbl_scwts_sarujanan (
  activity_id text NOT NULL, activity_date date, developer text DEFAULT 'sarujanan',
  project_code text NOT NULL, project_name text, requirement_id text, deliverable_id text,
  activity_type text, activity_title text, activity_summary text, systems_touched text,
  files_touched text, evidence_refs text, reusable_asset_created boolean, reusable_pattern text,
  validation_rule text, gap_or_risk text, next_action text, status text DEFAULT 'completed',
  priority text DEFAULT 'medium', llm_queryable boolean, company_knowledge_candidate boolean,
  memory_tags text, source_skill_file text, source_type text DEFAULT 'skill_file',
  created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(),
  PRIMARY KEY (project_code, activity_id));

INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A01', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'validation', 'Validate the LEDs One migration and keep the old database for two values only', 'Confirmed Dashboard V2 runs on LEDSone through the pg_temp source layer with the business SQL unchanged. The old order_management_copy is read for exactly two things: the isdeleted flag and the 10 order sources LEDSone does not carry. Google Ads product_performance holds superseded duplicate ids, so the latest version per id is used. Two fallback rules added during the migration (catalogue image, PO-header container) were reverted on instruction because they were new business rules.', 'PostgreSQL ledsone; PostgreSQL order_management_copy', 'dashboard-v2-sql/v2_sources.py; dashboard-v2-sql/build_v2.py', 'combo links 366/366; order lines 8,855/8,855; Google Ads 802,585/802,585 exact', TRUE, 'Migrate a database by recreating the OLD table shapes as temp views, so business SQL never changes', 'Every migrated field compared old-vs-new before use', 'Old DB still required for isdeleted and 10 order sources', 'Ask the DB owner to carry isdeleted and the missing order sources into LEDSone', 'completed', 'high', TRUE, TRUE, 'migration,ledsone,temp-views,source-layer', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
