VALUES ('D01-A02', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'implementation', 'Fix the product images, the Record ID and the duplicated combo rows', 'Images now come from the database catalogue (inventory.product_images, then product_media main-image) when the supplier and listing photos are blank, clearing all 81 empty image cells. The Record ID is written once per product with a rowspan instead of repeating on every marketplace row, and is numbered in display order. The Combos tab no longer repeats component-only rows.', 'PostgreSQL ledsone', 'dashboard-v2-sql/build_v2.py; dashboard-v2-sql/make_html.py', '81 blank images -> 0; one Record ID per product group', FALSE, 'Fill a blank display field from the catalogue only after the primary sources are exhausted', 'No product may appear twice within one tab', 'None', 'None', 'completed', 'medium', TRUE, TRUE, 'images,record-id,deduplication', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
