VALUES ('D01-A03', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'implementation', 'Order rows by data completeness and hide the three combo-only columns', 'Default display order is container plus received date first, then container only, then neither, so the most complete rows lead. On the Components tab the three combo columns (Combo SKU, Image, Created) are hidden because they are always blank there. Sorting, filters and paging were untouched.', 'local filesystem', 'dashboard-v2-sql/make_html.py', 'display-priority bands 1/2/3 applied; column set unchanged on the Combos tab', FALSE, 'Order by completeness only in the default view, so an explicit user sort always wins', 'Data values must not change when only the order changes', 'None', 'None', 'completed', 'medium', TRUE, TRUE, 'ui,ordering,columns', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
