INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A05', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'investigation', 'Trace where container and received date are lost, across three systems', 'Compared the admin UK Supply List, the Inventory team dashboard and LEDSone SKU by SKU over 13 sample groups (IMACCW, LHXSHE27BM, SU1318 group, CRSP cables, CRSFX120, CBSF95, MBWHBSL, LSCY2902, LSGLST, LSMS3202). Proved that final_containers.status=''completed'' is set at DISPATCH, not receipt: UK Container 8th 2026 is completed with an invoice ship-by of 9 Sep, 0 of 157 lines arrived and zero stock. Also found SKU re-coding (IMACCW receipt recorded under IMAC7714CW), containers never assigned on shipped POs, and warehouse id 33 missing from inventory.warehouse.', 'PostgreSQL ledsone; admin dashboard.digitweblk.com screenshots', 'validation/DB_Designer_Gap_Report_Container_Received_20260915.md', '7 gaps evidenced with counts; 12 database fixes requested (D1-D12)', TRUE, 'Prove a data gap by reconciling three independent systems row by row before proposing any code change', 'No count is reported without the SELECT that produced it', 'Supply list, receipts and container links live only in the admin system', 'Send the gap report to the database designer and track D1-D12', 'completed', 'high', TRUE, TRUE, 'gap-report,container,received-date,three-source-audit', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
