INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A06', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'implementation', 'Fill container and received date from the last arrived PO and the warehouse history', 'Rule A shows the last ARRIVED PO when the newest PO has not arrived (9 components); Rule B fills the received date from the latest warehouse stock-in even when older than the latest PO (21 components). Received coverage rose from 188 to 216 of 269, and container coverage stayed at 244. Both rules were approved by the user after the LSMS3202 and LSGLST evidence was shown.', 'PostgreSQL ledsone', 'dashboard-v2-sql/build_v2.py', 'received dates 188/268 -> 216/269; container 244/269; build RESULT PASS', FALSE, 'A stop-gap rule must be documented as replaceable, so the real source can retire it cleanly', 'Every filled value carries its source in the row notes', 'History text is a frozen partial copy (26 Aug), so it cannot see later receipts', 'Replace with the real supply tables when they exist', 'completed', 'medium', TRUE, TRUE, 'received-date,fallback,rule-a,rule-b', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
