INSERT INTO daily_task.tbl_scwts_sarujanan (activity_id, activity_date, developer, project_code, project_name, requirement_id, deliverable_id, activity_type, activity_title, activity_summary, systems_touched, files_touched, evidence_refs, reusable_asset_created, reusable_pattern, validation_rule, gap_or_risk, next_action, status, priority, llm_queryable, company_knowledge_candidate, memory_tags, source_skill_file, source_type)
VALUES ('D01-A07', DATE '2026-09-15', 'sarujanan', 'scwts', 'Supplier-to-Customer Workflow Tracking System', 'REQ-03', 'D01', 'implementation', 'Start the responsive rebuild: release the fixed shell and scale every control', 'Found the cause of the poor scaling: the page is locked to 100vh with overflow hidden, so on narrow or short screens the header, filters and KPI cards consume the height and the pager becomes unreachable (measured failing at 1024, 600 and 375). Added clamp() scaling for fonts, padding, gaps, icons and images, released the fixed shell below 1024px or 700px height, turned the filter bar into a grid and let the app bar wrap so Theme and CSV stop falling off screen at 375px. Measured before/after at 8 viewports.', 'local filesystem; headless Chrome', 'dashboard-v2-sql/make_html.py', '8 viewports measured; pager reachable at every width; 1920 and 1440 pixel-identical to before', TRUE, 'Prove a CSS-only change with md5 of the file outside the style block plus a driven interaction harness', 'Payload, script and markup bytes identical before and after a CSS change', 'Fixed shell kept on desktop, so 1366x768 still shows a short table', 'Finish the validation report and publish nothing until approved', 'completed', 'high', TRUE, TRUE, 'responsive,css,clamp,shell-release', '2026-09-15__sarujanan__scwts__REQ-03-D01.md', 'skill_file')
